#!/usr/bin/env node
// Black-box extraction of IDNA2008/UTS46 data tables by probing
// /workspace/dataset/test3_executable (PyInstaller binary; never `python`).
//
// Sweeps:
//   A: UTS46 remap per code point (batch probe with anchored labels behind a leading '.')
//   B: strict single-char-label validity (group testing + bisection)
//   C: joiner context sets X+ZWJ / X+ZWNJ for code points valid in B
//
// Intermediate results are cached to /output/tools/cache-*.json so a crash
// loses no progress; finally writes /output/lib/idnaTables.mjs.
//
// NOTE on anchors: every anchor starts AND ends with a digit. NFC (applied by
// uts46_remap) has no canonical composition pairs starting with a decimal
// digit, so an anchor can never merge with a mapped combining mark. (A letter
// anchor such as 'z' would merge: 'z'+U+0301 -> U+017A, corrupting slices.)

import { execFile } from 'node:child_process';
import fs from 'node:fs';

const EXE = '/workspace/dataset/test3_executable';
const TOOLS = '/output/tools';
const LIB = '/output/lib';
const CONCURRENCY = 24;

const CACHE_REMAP = `${TOOLS}/cache-remap.json`;
const CACHE_VALID = `${TOOLS}/cache-valid.json`;
const CACHE_VIRAMA = `${TOOLS}/cache-virama.json`;
const CACHE_ZWJOK = `${TOOLS}/cache-zwjok.json`;
const CACHE_ANOM = `${TOOLS}/cache-anomalies.json`;

// ---------------------------------------------------------------- runner ---
let running = 0;
const waiters = [];
function runProbe(domain) {
  return new Promise((resolve, reject) => {
    const start = () => {
      running++;
      execFile(EXE, ['--domain', domain, '--strict', 'True'],
        { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, timeout: 60000 },
        (err, stdout, stderr) => {
          running--;
          const next = waiters.shift();
          if (next) next();
          if (err && err.code !== undefined && typeof err.code === 'number') {
            // non-zero exit: still capture stdout for reporting
            resolve({ code: err.code, stdout: stdout ?? '', stderr: stderr ?? '' });
          } else if (err) {
            reject(err); // spawn failure, timeout, etc.
          } else {
            resolve({ code: 0, stdout, stderr: '' });
          }
        });
    };
    if (running < CONCURRENCY) start();
    else waiters.push(start);
  });
}

// stdout = line1 + '\n' + remapped + '\n' + ('True'|'False') + '\n' [+ extra]
// remapped may itself contain raw newlines; strip the bool from the END.
function parseProbe(stdout) {
  const i = stdout.indexOf('\n');
  const line1 = i === -1 ? stdout : stdout.slice(0, i);
  let rest = i === -1 ? '' : stdout.slice(i + 1);
  let lenOk = null;
  if (rest.endsWith('\nTrue\n')) { lenOk = true; rest = rest.slice(0, -6); }
  else if (rest.endsWith('\nFalse\n')) { lenOk = false; rest = rest.slice(0, -7); }
  else if (rest === 'True\n') { lenOk = true; rest = ''; }
  else if (rest === 'False\n') { lenOk = false; rest = ''; }
  return { line1, remapped: rest, lenOk };
}

const anomalies = []; // code points with exit code != 0
function noteAnomaly(cp, code, info) {
  anomalies.push({ cp, code, info });
  console.error(`ANOMALY: cp=U+${cp.toString(16).toUpperCase()} exit=${code} ${info}`);
}

// ------------------------------------------------------------- utilities ---
const MAX_CP = 0x10FFFF;
const isSurrogate = (cp) => cp >= 0xD800 && cp <= 0xDFFF;

// All sweep code points: 0x01..0x10FFFF excluding 0x2E and surrogates.
function allCodePoints() {
  const out = [];
  for (let cp = 1; cp <= MAX_CP; cp++) {
    if (cp === 0x2E || isSurrogate(cp)) continue;
    out.push(cp);
  }
  return out;
}

function toRanges(sortedCps) {
  const ranges = [];
  for (const cp of sortedCps) {
    const last = ranges[ranges.length - 1];
    if (last && cp === last[1] + 1) last[1] = cp;
    else ranges.push([cp, cp]);
  }
  return ranges;
}

// ------------------------------------------------------------ Sweep A -------
// Batch probe: domain '.' + (anchor_k + char_k).join('.')
// anchors start and end with a digit to be NFC-inert at both ends.
async function probeRemapBatch(cps) {
  const chars = cps.map((cp) => String.fromCodePoint(cp));
  const anchors = cps.map((_, k) => k.toString(36) + '0');
  const domain = '.' + cps.map((_, k) => anchors[k] + chars[k]).join('.');
  const { code, stdout } = await runProbe(domain);
  if (code !== 0) {
    // isolate the crashing code point(s)
    const results = new Array(cps.length);
    for (let k = 0; k < cps.length; k++) results[k] = await probeRemapSingle(cps[k], chars[k]);
    return results;
  }
  const { line1, remapped } = parseProbe(stdout);
  const ok = line1.startsWith('strict_encode_error') && remapped.startsWith('.');
  let parts = null;
  if (ok) {
    parts = remapped.split('.');
    if (parts.length === cps.length + 1) {
      for (let k = 0; k < cps.length; k++) {
        if (!parts[k + 1].startsWith(anchors[k])) { parts = null; break; }
      }
    } else {
      parts = null;
    }
  }
  if (!parts) {
    // some char mapped to something containing '.' (or anchor check failed):
    // rerun each char of this batch individually.
    const results = new Array(cps.length);
    for (let k = 0; k < cps.length; k++) results[k] = await probeRemapSingle(cps[k], chars[k]);
    return results;
  }
  return cps.map((cp, k) => {
    const mapping = parts[k + 1].slice(anchors[k].length);
    return classifyMapping(cp, chars[k], mapping);
  });
}

function classifyMapping(cp, char, mapping) {
  if (mapping === char) return { cp, type: 'pass' };
  if (mapping === '') return { cp, type: 'drop' };
  return { cp, type: 'map', to: mapping };
}

// Individual fallback: domain '.' + '0' + char ; mapping = remapped.slice(2).
async function probeRemapSingle(cp, char = String.fromCodePoint(cp)) {
  const { code, stdout } = await runProbe('.' + '0' + char);
  if (code !== 0) {
    noteAnomaly(cp, code, 'remap-single');
    return { cp, type: 'pass', anomaly: true };
  }
  const { remapped } = parseProbe(stdout);
  if (!remapped.startsWith('.0')) {
    // should not happen (digit anchor is NFC-inert); treat as anomaly
    noteAnomaly(cp, 0, `unexpected remapped prefix ${JSON.stringify(remapped.slice(0, 8))}`);
    return { cp, type: 'pass', anomaly: true };
  }
  return classifyMapping(cp, char, remapped.slice(2));
}

async function sweepA() {
  if (fs.existsSync(CACHE_REMAP)) {
    const c = JSON.parse(fs.readFileSync(CACHE_REMAP, 'utf8'));
    console.log(`Sweep A: loaded cache (${c.drops.length} drops, ${c.maps.length} maps)`);
    return c;
  }
  const cps = allCodePoints();
  const BATCH = 2000;
  const drops = [];
  const maps = []; // [cp, to]
  let done = 0;
  const tasks = [];
  for (let i = 0; i < cps.length; i += BATCH) {
    const chunk = cps.slice(i, i + BATCH);
    tasks.push(async () => {
      const results = await probeRemapBatch(chunk);
      for (const r of results) {
        if (r.type === 'drop') drops.push(r.cp);
        else if (r.type === 'map') maps.push([r.cp, r.to]);
      }
      done += chunk.length;
      if (done % 100000 < BATCH) console.log(`Sweep A: ${done}/${cps.length}`);
    });
  }
  // run with pool already limiting concurrency inside runProbe; just launch all
  await Promise.all(tasks.map((t) => t()));
  drops.sort((a, b) => a - b);
  maps.sort((a, b) => a[0] - b[0]);
  const out = { drops, maps };
  fs.writeFileSync(CACHE_REMAP, JSON.stringify(out));
  console.log(`Sweep A done: ${drops.length} drops, ${maps.length} maps`);
  return out;
}

// ------------------------------------------------------------ Sweep B/C -----
// Group testing: domain of labels encodes (line1 starts with b') iff all ok.
async function encodeOk(domain, cpsForAnomaly) {
  const { code, stdout } = await runProbe(domain);
  if (code !== 0) return { ok: false, crashed: true };
  const line1 = stdout.slice(0, stdout.indexOf('\n'));
  return { ok: line1.startsWith("b'"), crashed: false };
}

// Returns array of valid cps from `cps` (order preserved).
async function groupTest(cps, makeDomain) {
  if (cps.length === 0) return [];
  const domain = makeDomain(cps);
  const { ok } = await encodeOk(domain);
  if (ok) return cps.slice();
  if (cps.length === 1) {
    // distinguish crash from plain invalid
    const { code } = await runProbe(makeDomain(cps));
    if (code !== 0) noteAnomaly(cps[0], code, 'groupTest-single');
    return [];
  }
  const mid = cps.length >> 1;
  const [a, b] = await Promise.all([
    groupTest(cps.slice(0, mid), makeDomain),
    groupTest(cps.slice(mid), makeDomain),
  ]);
  return a.concat(b);
}

async function sweepB() {
  if (fs.existsSync(CACHE_VALID)) {
    const c = JSON.parse(fs.readFileSync(CACHE_VALID, 'utf8'));
    console.log(`Sweep B: loaded cache (${c.length} valid)`);
    return c;
  }
  const cps = allCodePoints();
  const CHUNK = 20; // worst-case single-char punycode ~9B; 20*10=200 < 253
  const valid = [];
  const tasks = [];
  let doneChunks = 0;
  const totalChunks = Math.ceil(cps.length / CHUNK);
  for (let i = 0; i < cps.length; i += CHUNK) {
    const chunk = cps.slice(i, i + CHUNK);
    tasks.push(async () => {
      const v = await groupTest(chunk, (cs) => cs.map((c) => String.fromCodePoint(c)).join('.'));
      for (const c of v) valid.push(c);
      doneChunks++;
      if (doneChunks % 5000 === 0) console.log(`Sweep B: ${doneChunks}/${totalChunks} chunks`);
    });
  }
  await Promise.all(tasks.map((t) => t()));
  valid.sort((a, b) => a - b);
  fs.writeFileSync(CACHE_VALID, JSON.stringify(valid));
  console.log(`Sweep B done: ${valid.length} valid-alone code points`);
  return valid;
}

async function sweepC(validAlone) {
  let virama, zwjok;
  if (fs.existsSync(CACHE_VIRAMA)) {
    virama = JSON.parse(fs.readFileSync(CACHE_VIRAMA, 'utf8'));
    console.log(`Sweep C: loaded virama cache (${virama.length})`);
  }
  if (fs.existsSync(CACHE_ZWJOK)) {
    zwjok = JSON.parse(fs.readFileSync(CACHE_ZWJOK, 'utf8'));
    console.log(`Sweep C: loaded zwjok cache (${zwjok.length})`);
  }
  if (virama && zwjok) return { virama, zwjok };

  const CHUNK = 16; // 2-char labels, worst-case ~13B each; 16*14=224 < 253
  async function runSet(joiner) {
    const out = [];
    const tasks = [];
    let doneChunks = 0;
    const totalChunks = Math.ceil(validAlone.length / CHUNK);
    for (let i = 0; i < validAlone.length; i += CHUNK) {
      const chunk = validAlone.slice(i, i + CHUNK);
      tasks.push(async () => {
        const v = await groupTest(chunk,
          (cs) => cs.map((c) => String.fromCodePoint(c) + joiner).join('.'));
        for (const c of v) out.push(c);
        doneChunks++;
        if (doneChunks % 2000 === 0) console.log(`Sweep C: ${doneChunks}/${totalChunks} chunks`);
      });
    }
    await Promise.all(tasks.map((t) => t()));
    out.sort((a, b) => a - b);
    return out;
  }
  if (!virama) {
    virama = await runSet('‍');
    fs.writeFileSync(CACHE_VIRAMA, JSON.stringify(virama));
    console.log(`Sweep C virama (X+ZWJ ok... ZWNJ) done: ${virama.length}`);
  }
  if (!zwjok) {
    zwjok = await runSet('‍');
    fs.writeFileSync(CACHE_ZWJOK, JSON.stringify(zwjok));
    console.log(`Sweep C zwjok done: ${zwjok.length}`);
  }
  return { virama, zwjok };
}

// ----------------------------------------------------------- emit tables ----
function emitTables({ drops, maps }, valid, virama, zwjok) {
  const validRanges = toRanges(valid);
  const viramaRanges = toRanges(virama);
  const zwjokRanges = toRanges(zwjok);
  const dropRanges = toRanges(drops);

  const src = `// GENERATED FILE — do not edit by hand.
// Black-box reconstruction of the Python \`idna\` package's data tables
// (IDNA2008 validity + UTS46 remap, non-transitional) by probing a reference
// executable. Regenerate with: node /output/tools/extract-tables.mjs
//
// Conventions:
//  - Ranges are sorted, inclusive [lo, hi] pairs.
//  - REMAP_MAP entries are [cp, replacement] sorted by cp.
//  - Code points not in any map/drop structure remap as 'pass'.
//    (cp 0x00, surrogates 0xD800..0xDFFF and 0x2E '.' are all 'pass';
//     0x00 and surrogates are never valid alone; validity of 0x2E is
//     irrelevant since it is a label separator.)

const VALID_RANGES = ${JSON.stringify(validRanges)};
const VIRAMA_RANGES = ${JSON.stringify(viramaRanges)};
const ZWJOK_RANGES = ${JSON.stringify(zwjokRanges)};
const REMAP_DROP_RANGES = ${JSON.stringify(dropRanges)};
const REMAP_MAP = ${JSON.stringify(maps)};

function inRanges(ranges, cp) {
  let lo = 0, hi = ranges.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const r = ranges[mid];
    if (cp < r[0]) hi = mid - 1;
    else if (cp > r[1]) lo = mid + 1;
    else return true;
  }
  return false;
}

/** true iff the code point is valid as a one-character label under strict IDNA2008. */
export function isValidAlone(cp) {
  if (cp < 1 || cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) return false;
  return inRanges(VALID_RANGES, cp);
}

/** true iff label (X + U+200D) ... virama context: X + U+200C encodes strictly. */
export function isVirama(cp) {
  return inRanges(VIRAMA_RANGES, cp);
}

/** true iff X + U+200D encodes strictly (joiner context allows following ZWJ). */
export function isZwjOk(cp) {
  return inRanges(ZWJOK_RANGES, cp);
}

/** UTS46 remap of a single code point: {type:'pass'} | {type:'drop'} | {type:'map', to}. */
export function remapCodepoint(cp) {
  let lo = 0, hi = REMAP_MAP.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const e = REMAP_MAP[mid];
    if (cp < e[0]) hi = mid - 1;
    else if (cp > e[0]) lo = mid + 1;
    else return { type: 'map', to: e[1] };
  }
  if (inRanges(REMAP_DROP_RANGES, cp)) return { type: 'drop' };
  return { type: 'pass' };
}
`;
  fs.mkdirSync(LIB, { recursive: true });
  fs.writeFileSync(`${LIB}/idnaTables.mjs`, src);
  console.log(`Wrote ${LIB}/idnaTables.mjs (${(src.length / 1024).toFixed(0)} KiB)`);
  return { validRanges, viramaRanges, zwjokRanges, dropRanges, mapCount: maps.length };
}

// ----------------------------------------------------------------- main ----
const t0 = Date.now();
const remap = await sweepA();
const valid = await sweepB();
const { virama, zwjok } = await sweepC(valid);
const stats = emitTables(remap, valid, virama, zwjok);

if (anomalies.length) {
  fs.writeFileSync(CACHE_ANOM, JSON.stringify(anomalies, null, 2));
  console.log(`Anomalies (exit!=0 or unexpected): ${anomalies.length} -> ${CACHE_ANOM}`);
} else {
  console.log('Anomalies: none');
}
console.log(`Counts: validAlone=${valid.length} validRanges=${stats.validRanges.length} ` +
  `drops=${remap.drops.length} dropRanges=${stats.dropRanges.length} maps=${remap.maps.length} ` +
  `virama=${virama.length} viramaRanges=${stats.viramaRanges.length} ` +
  `zwjok=${zwjok.length} zwjokRanges=${stats.zwjokRanges.length}`);
console.log(`Elapsed: ${((Date.now() - t0) / 1000).toFixed(1)}s`);

