#!/usr/bin/env node
// Verification for /output/lib/idnaTables.mjs against the reference executable.
//  1. Asserts the expected values pinned by the task spec.
//  2. Re-probes 50 random code points per sweep against the executable.
//  3. Spot-checks several real domains end-to-end (UTS46 remap via the table
//     + NFC must equal the executable's remapped line).
// Uses the same NFC-inert digit-anchor probe trick as the extractor
// (a letter anchor like 'z' would NFC-merge with combining marks).

import { execFile } from 'node:child_process';
import { isValidAlone, isVirama, isZwjOk, remapCodepoint }
  from '/output/lib/idnaTables.mjs';

const EXE = '/workspace/dataset/test3_executable';
const CONCURRENCY = 24;

let failures = 0;
function check(cond, msg) {
  if (!cond) { failures++; console.error(`FAIL: ${msg}`); }
}

// ---------------------------------------------------------------- runner ---
let running = 0;
const waiters = [];
function runProbe(domain) {
  return new Promise((resolve, reject) => {
    const start = () => {
      running++;
      execFile(EXE, ['--domain', domain, '--strict', 'True'],
        { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, timeout: 60000 },
        (err, stdout, stderr) => {
          running--;
          const next = waiters.shift();
          if (next) next();
          if (err && typeof err.code === 'number') {
            resolve({ code: err.code, stdout: stdout ?? '', stderr: stderr ?? '' });
          } else if (err) reject(err);
          else resolve({ code: 0, stdout, stderr: '' });
        });
    };
    if (running < CONCURRENCY) start();
    else waiters.push(start);
  });
}

function parseProbe(stdout) {
  const i = stdout.indexOf('\n');
  const line1 = i === -1 ? stdout : stdout.slice(0, i);
  let rest = i === -1 ? '' : stdout.slice(i + 1);
  if (rest.endsWith('\nTrue\n')) rest = rest.slice(0, -6);
  else if (rest.endsWith('\nFalse\n')) rest = rest.slice(0, -7);
  else if (rest === 'True\n' || rest === 'False\n') rest = '';
  return { line1, remapped: rest };
}

// --------------------------------------------------- 1. pinned expectations --
console.log('== Pinned expectations ==');
const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
check(eq(remapCodepoint(0x41), { type: 'map', to: 'a' }), "remap 'A' -> 'a'");
check(eq(remapCodepoint(0xAD), { type: 'drop' }), 'remap U+00AD -> drop');
check(eq(remapCodepoint(0x3002), { type: 'map', to: '.' }), 'remap U+3002 -> "."');
check(eq(remapCodepoint(0xFF21), { type: 'map', to: 'a' }), 'remap U+FF21 -> "a"');
check(eq(remapCodepoint(0xDF), { type: 'pass' }), 'remap U+00DF ß -> pass');
check(eq(remapCodepoint(0x1F600), { type: 'pass' }), 'remap U+1F600 -> pass');
check(eq(remapCodepoint(0x200B), { type: 'drop' }), 'remap U+200B -> drop');
check(eq(remapCodepoint(0x00), { type: 'pass' }), 'remap U+0000 -> pass (hardcoded)');
check(eq(remapCodepoint(0x2E), { type: 'pass' }), 'remap U+002E -> pass (hardcoded)');
check(eq(remapCodepoint(0xD800), { type: 'pass' }), 'remap U+D800 -> pass (hardcoded)');

check(isValidAlone(0x4F8B) === true, 'U+4F8B 例 valid alone');
check(isValidAlone(0x41) === true, "'A' valid alone");
check(isValidAlone(0x5F) === false, "'_' invalid alone");
check(isValidAlone(0x1F600) === false, 'U+1F600 invalid alone');
check(isValidAlone(0x2D) === false, "'-' invalid alone");
check(isValidAlone(0x00) === false, 'U+0000 not valid (hardcoded)');
check(isValidAlone(0xD800) === false, 'U+D800 not valid (hardcoded)');

check(isVirama(0x94D) === true, 'U+094D Devanagari virama in VIRAMA set');
check(isZwjOk(0x61) === true, "'a' in ZWJOK set");
check(isVirama(0x4F8B) === false, 'U+4F8B not in VIRAMA set');
check(isZwjOk(0x4F8B) === false, 'U+4F8B not in ZWJOK set');
console.log(failures === 0 ? 'all pinned expectations OK' : `${failures} pinned failures`);

// ------------------------------------------------- 2. random re-probes -------
const rng = (() => { let s = 0xC0FFEE; return () => (s = (s * 1103515245 + 12345) & 0x7FFFFFFF) / 0x80000000; })();
const isSurrogate = (cp) => cp >= 0xD800 && cp <= 0xDFFF;
function randomCp() {
  for (;;) {
    const cp = 1 + Math.floor(rng() * 0x10FFFF);
    if (cp !== 0x2E && !isSurrogate(cp)) return cp;
  }
}

async function verifyRemap(cp) {
  const ch = String.fromCodePoint(cp);
  const { code, stdout } = await runProbe('.' + '0' + ch);
  check(code === 0, `remap probe exit!=0 for U+${cp.toString(16)}`);
  if (code !== 0) return;
  const { remapped } = parseProbe(stdout);
  if (!remapped.startsWith('.0')) { check(false, `remap probe weird prefix U+${cp.toString(16)}`); return; }
  const actual = remapped.slice(2);
  const r = remapCodepoint(cp);
  const expected = r.type === 'pass' ? ch : r.type === 'drop' ? '' : r.to;
  check(actual === expected,
    `remap mismatch U+${cp.toString(16).toUpperCase()}: exe=${JSON.stringify(actual)} table=${JSON.stringify(expected)}`);
}

async function verifyValid(cp) {
  const { code, stdout } = await runProbe(String.fromCodePoint(cp));
  check(code === 0, `validity probe exit!=0 for U+${cp.toString(16)}`);
  if (code !== 0) return;
  const { line1 } = parseProbe(stdout);
  const actual = line1.startsWith("b'");
  check(actual === isValidAlone(cp),
    `validity mismatch U+${cp.toString(16).toUpperCase()}: exe=${actual} table=${isValidAlone(cp)}`);
}

